import {readBoundedBody} from '../secure-upload/bounded-request.ts';
import {createClient} from '@supabase/supabase-js';
import {SaxesParser} from 'saxes';
import {withFiscalCors} from '../_shared/fiscal-cors.ts';
import {corsHeaders} from '../_shared/cors.ts';
import {requireActiveTenant} from '../_shared/active-tenant.ts';
import {resolveHubFiscalToken} from '../_shared/fiscal-poll.ts';
import {fiscalHubBaseUrl} from '../_shared/fiscal-transport.ts';
import {downloadExistingXml,inspectExistingXml,type EmissionIdentity,type XmlReader} from './preview.ts';
const reply=(status:number,body:unknown)=>new Response(JSON.stringify(body),{status,headers:{...corsHeaders,'Content-Type':'application/json','Cache-Control':'no-store'}});
const uuid=(s:unknown):s is string=>typeof s==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(s);
Deno.serve(withFiscalCors(async req=>{
 if(req.method==='OPTIONS')return reply(200,{});if(req.method!=='POST')return reply(405,{error:'method_not_allowed'});
 try{
  const raw=await readBoundedBody(req,2048);const body=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw));
  if(!body||!uuid(body.tenant_id)||(uuid(body.emission_id)===uuid(body.observation_id))||(body.emission_id!==undefined&&!uuid(body.emission_id))||(body.observation_id!==undefined&&!uuid(body.observation_id))||Object.keys(body).some(k=>!['tenant_id','emission_id','observation_id'].includes(k)))return reply(400,{error:'invalid_request'});
  const authorization=req.headers.get('Authorization')||'';if(!authorization.startsWith('Bearer '))return reply(401,{error:'unauthorized'});
  const url=Deno.env.get('SUPABASE_URL')!,caller=createClient(url,Deno.env.get('SUPABASE_ANON_KEY')!,{global:{headers:{Authorization:authorization}},auth:{persistSession:false}});
  const identity=await caller.auth.getUser();if(identity.error||!identity.data.user)return reply(401,{error:'unauthorized'});
  const context=requireActiveTenant(req,body.tenant_id);if(context)return context;
  const allowed=async()=>{const r=await caller.rpc('get_finance_access',{_tenant_id:body.tenant_id});return !r.error&&r.data===true;};
  if(!await allowed())return reply(403,{error:'finance_access_denied'});
  const admin=createClient(url,Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false}});
  let emissionId=body.emission_id;
  if(body.observation_id){const o=await admin.from('finance_fiscal_observations').select('emission_id').eq('tenant_id',body.tenant_id).eq('id',body.observation_id).single();if(o.error||!o.data)return reply(404,{error:'fiscal_observation_not_found'});emissionId=o.data.emission_id;}
  const readEmission=()=>admin.from('hub_fiscal_emissions').select('id,tenant_id,doc_type,environment,status,dispatch_state,hub_document_id,access_key,emitter_cnpj,emitter_id,number,series,authorization_protocol').eq('tenant_id',body.tenant_id).eq('id',emissionId).single();
  const row=await readEmission();
  if(row.error||!row.data||!['cte','nfse'].includes(row.data.doc_type)||row.data.environment!=='production'||row.data.dispatch_state!=='recorded'||!row.data.hub_document_id)return reply(409,{error:'fiscal_existing_reference_unavailable'});
  const token=await resolveHubFiscalToken(admin,{tenantId:body.tenant_id,emitterId:row.data.emitter_id,environment:row.data.environment,scope:row.data.doc_type,encryptionKey:Deno.env.get('AGVLOG_ENCRYPTION_KEY')||'',getSecret:name=>Deno.env.get(name)});
  if(!token)return reply(409,{error:'fiscal_existing_reference_unavailable'});
  if(!await allowed())return reply(403,{error:'finance_access_denied'});
  const bytes=await downloadExistingXml(fiscalHubBaseUrl(Deno.env.get('HUB_FISCAL_BASE_URL')),token,row.data.hub_document_id);
  const result=await inspectExistingXml(bytes,row.data as EmissionIdentity,()=>new SaxesParser({xmlns:true}) as unknown as XmlReader);
  if(!await allowed())return reply(403,{error:'finance_access_denied'});
  const current=await readEmission();if(current.error||JSON.stringify(current.data)!==JSON.stringify(row.data))return reply(409,{error:'fiscal_evidence_source_changed'});
  return reply(200,{...result,observation_id:body.observation_id||null});
 }catch(error){const code=error instanceof Error&&/^fiscal_[a-z_]+$/.test(error.message)?error.message:'fiscal_evidence_preview_failed';return reply(422,{error:code});}
}));

export async function readBoundedBody(request:Request,maxBytes:number,timeoutMs=15000){
 if(!request.body)throw new Error('upload_empty_body');
 const reader=request.body.getReader(),chunks:Uint8Array[]=[];let size=0,timer:ReturnType<typeof setTimeout>|undefined;
 const timeout=new Promise<never>((_,reject)=>{timer=setTimeout(()=>{reject(new Error('upload_body_timeout'));void reader.cancel().catch(()=>{});},timeoutMs);});
 try{
  while(true){const next=await Promise.race([reader.read(),timeout]);if(next.done)break;
   size+=next.value.length;if(size>maxBytes){await reader.cancel();throw new Error('upload_body_too_large');}chunks.push(next.value);
  }
  const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}return bytes;
 }finally{if(timer!==undefined)clearTimeout(timer);reader.releaseLock();}
}

import { appOrigin, corsHeaders } from './cors.ts';

// Explicitly approved billing origins. Never trust an entire hosting domain:
// other customers can publish there.
const BILLING_PRODUCTION_ORIGIN = 'https://agvlogistica.vercel.app';
// Remove this preview when its deployment is retired.
const BILLING_PREVIEW_ORIGIN = 'https://agvlog-preview-thomaz-20260831.veituma.chatgpt.site';

function allowedFiscalOrigins(): Set<string> {
  // An invalid primary configuration must remain fail-closed.
  if (!appOrigin) return new Set();
  const allowed = new Set([appOrigin, BILLING_PRODUCTION_ORIGIN]);
  const configured = Deno.env.get('AGVLOG_FISCAL_PREVIEW_ORIGINS') ?? BILLING_PREVIEW_ORIGIN;
  for (const candidate of configured.split(',')) {
    const origin = candidate.trim();
    if (!origin) continue;
    try {
      const url = new URL(origin);
      if (url.protocol === 'https:' && url.origin === origin) allowed.add(origin);
    } catch {
      // Invalid entries never grant browser access.
    }
  }
  return allowed;
}

const allowedOrigins = allowedFiscalOrigins();

/** Apply the same exact-origin policy to preflight, success and error responses.
 * This supplements (and never replaces) each handler's JWT/tenant checks.
 * Requests without Origin retain the existing server/cron authentication.
 */
export function withFiscalCors(handler: (request: Request) => Response | Promise<Response>) {
  return async (request: Request): Promise<Response> => {
    const origin = request.headers.get('Origin');
    const headers = new Headers(corsHeaders);
    headers.delete('Access-Control-Allow-Origin');
    headers.set('Access-Control-Max-Age', '600');
    if (origin !== null && !allowedOrigins.has(origin)) {
      headers.set('Content-Type', 'application/json');
      return new Response(JSON.stringify({ success: false, error: { code: 'ORIGIN_NOT_ALLOWED' } }), { status: 403, headers });
    }
    if (origin) headers.set('Access-Control-Allow-Origin', origin);
    const response = await handler(request);
    const responseHeaders = new Headers(response.headers);
    responseHeaders.delete('Access-Control-Allow-Origin');
    // Preserve other cache dimensions while adding the request Origin dimension.
    const vary = new Set((responseHeaders.get('Vary') || '').split(',').map(value => value.trim()).filter(Boolean));
    vary.add('Origin');
    headers.forEach((value, key) => responseHeaders.set(key, value));
    responseHeaders.set('Vary', [...vary].join(', '));
    return new Response(response.body, { status: response.status, statusText: response.statusText, headers: responseHeaders });
  };
}

const DEFAULT_ALLOWED_HEADERS = [
  "authorization",
  "x-client-info",
  "apikey",
  "content-type",
  "x-supabase-client-platform",
  "x-supabase-client-platform-version",
  "x-supabase-client-runtime",
  "x-supabase-client-runtime-version",
  "x-retry-count",
  "x-agvlog-tenant-id",
  "x-agvlog-cron-secret",
  "x-fiscal-token",
  "x-webhook-secret",
  "x-webhook-id",
  "x-delivery-id",
  "x-hubfiscal-delivery",
  "x-hubfiscal-event",
  "x-hubfiscal-signature",
  "x-hubfiscal-timestamp",
  "x-correlation-id",
  "idempotency-key",
].join(", ");

declare const Deno: {
  env: { get(name: string): string | undefined };
};

// This repository is deployed at this exact public origin. Keep the environment
// override so previews/self-hosted environments can opt in explicitly, while the
// production deployment remains fail-closed if the secret is ever missing.
const PRODUCTION_APP_ORIGIN = "https://agvlog.lovable.app";

function readAllowedOrigin(): string | undefined {
  const configured = Deno.env.get("AGVLOG_APP_ORIGIN")?.trim() || PRODUCTION_APP_ORIGIN;

  try {
    const url = new URL(configured);
    const isSecure = url.protocol === "https:";
    const isLocal =
      url.protocol === "http:" &&
      (url.hostname === "localhost" || url.hostname === "127.0.0.1");

    if ((!isSecure && !isLocal) || url.origin !== configured.replace(/\/$/, "")) {
      console.error("AGVLOG_APP_ORIGIN must be an HTTPS origin or a localhost HTTP origin");
      return undefined;
    }

    return url.origin;
  } catch {
    console.error("AGVLOG_APP_ORIGIN is not a valid origin");
    return undefined;
  }
}

export const appOrigin = readAllowedOrigin();

/**
 * Shared, fail-closed CORS policy for Edge Functions.
 * AGVLOG_APP_ORIGIN may override the repository's exact production origin.
 * Server-to-server requests do not require Access-Control-Allow-Origin.
 */
export const corsHeaders: Readonly<Record<string, string>> = Object.freeze({
  ...(appOrigin ? { "Access-Control-Allow-Origin": appOrigin } : {}),
  "Access-Control-Allow-Headers": DEFAULT_ALLOWED_HEADERS,
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Max-Age": "86400",
  Vary: "Origin",
});

import { corsHeaders } from './cors.ts';

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function decodeJwtPayload(authorization: string | null): Record<string, unknown> | null {
  if (!authorization?.startsWith('Bearer ')) return null;
  const payload = authorization.slice(7).split('.')[1];
  if (!payload) return null;
  try {
    const normalized = payload.replace(/-/g, '+').replace(/_/g, '/');
    const padded = normalized.padEnd(Math.ceil(normalized.length / 4) * 4, '=');
    const parsed = JSON.parse(atob(padded));
    return parsed && typeof parsed === 'object' ? parsed as Record<string, unknown> : null;
  } catch {
    return null;
  }
}

/**
 * Must be called only after the endpoint has cryptographically verified the JWT.
 * The header transports the UI selection; the signed claim prevents a caller from
 * changing that selection by forging only the header or request body.
 */
export function requireActiveTenant(
  req: Request,
  tenantId: unknown,
  responseHeaders: Record<string, string> = corsHeaders,
): Response | null {
  const requestedTenant = typeof tenantId === 'string' ? tenantId : '';
  const headerTenant = req.headers.get('x-agvlog-tenant-id')?.trim() || '';
  const claims = decodeJwtPayload(req.headers.get('Authorization'));
  const claimTenant = typeof claims?.active_tenant_id === 'string' ? claims.active_tenant_id : '';

  if (!UUID.test(requestedTenant) || headerTenant !== requestedTenant || claimTenant !== requestedTenant) {
    return new Response(JSON.stringify({ error: 'tenant_context_mismatch' }), {
      status: 409,
      headers: { ...responseHeaders, 'Content-Type': 'application/json' },
    });
  }
  return null;
}

export function activeTenantFromVerifiedRequest(req: Request): string | null {
  const headerTenant = req.headers.get('x-agvlog-tenant-id')?.trim() || '';
  const claims = decodeJwtPayload(req.headers.get('Authorization'));
  const claimTenant = typeof claims?.active_tenant_id === 'string' ? claims.active_tenant_id : '';
  return UUID.test(headerTenant) && headerTenant === claimTenant ? headerTenant : null;
}

import { decryptFiscalCredential } from './fiscal-credential-crypto.ts';
import { requireHubEnvironment, selectScopedHubCredential } from './fiscal-environment.ts';

const MAX_POLL_AGE_MS = 15 * 60 * 1000;
const MAX_POLL_ATTEMPTS = 15;
const MAX_MISSING_PROVIDER_ATTEMPTS = 5;

type JsonRecord = Record<string, unknown>;

export type FiscalDocumentScope = 'cte' | 'nfse';
export type FiscalPollOutcome = 'issued' | 'rejected' | 'cancelled' | null;
const HUB_API_VERSION = '2026-08-27';

export interface HubFiscalCredential {
  doc_scope: string;
  environment: string | null;
  secret_name: string | null;
  secret_ciphertext: string | null;
}

interface ResolveHubFiscalTokenInput {
  tenantId: string;
  emitterId: string | null;
  environment?: string | null;
  scope: FiscalDocumentScope;
  encryptionKey: string;
  getSecret: (name: string) => string | undefined;
}

interface GetHubFiscalDocumentInput {
  baseUrl: string;
  hubDocumentId: string;
  token: string;
  fetcher?: typeof fetch;
}

export interface PollableFiscalDocument {
  id: string;
  tenant_id: string;
  created_at: string;
  status_check_attempts: number | null;
}

interface FiscalPollRpcClient {
  rpc: (
    name: string,
    args: Record<string, unknown>,
  ) => PromiseLike<{ data: unknown; error: { message?: string } | null }>;
}

interface TerminalizeFiscalPollInput {
  tenantId: string;
  documentKind: 'cte' | 'nfse';
  documentId: string;
  documentNumber: string | null;
  reasonCode: 'missing_provider_reference' | 'provider_unavailable' | 'provider_rate_limited' | 'status_timeout';
  attemptCount: number;
  firstSeenAt: string;
  context: JsonRecord;
}

function asRecord(value: unknown): JsonRecord {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
    ? value as JsonRecord
    : {};
}

function safeText(value: unknown, maxLength = 300): string | null {
  if (typeof value !== 'string' && typeof value !== 'number') return null;
  const text = String(value)
    .replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/gi, 'Bearer [redacted]')
    .replace(/\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\b/g, '[jwt-redacted]')
    .replace(/(password|senha|token|secret|cookie)\s*[:=]\s*[^,;\s]+/gi, '$1=[redacted]');
  return text.slice(0, maxLength);
}

export function selectHubFiscalCredential(
  credentials: HubFiscalCredential[],
  scope: FiscalDocumentScope,
  environment?: string | null,
): HubFiscalCredential | null {
  try {
    return selectScopedHubCredential(credentials, scope, requireHubEnvironment(environment));
  } catch {
    return null;
  }
}

// deno-lint-ignore no-explicit-any
export async function resolveHubFiscalToken(admin: any, input: ResolveHubFiscalTokenInput): Promise<string> {
  if (!input.tenantId || !input.emitterId) return '';

  const { data, error } = await admin
    .from('hub_fiscal_credentials')
    .select('doc_scope, environment, secret_name, secret_ciphertext')
    .eq('tenant_id', input.tenantId)
    .eq('emitter_id', input.emitterId)
    .eq('enabled', true);
  if (error) throw error;
  const credential = selectHubFiscalCredential(
    (data ?? []) as HubFiscalCredential[],
    input.scope,
    input.environment,
  );

  if (!credential) return '';
  if (credential.secret_ciphertext) {
    if (!input.encryptionKey) return '';
    try {
      return await decryptFiscalCredential(credential.secret_ciphertext, input.encryptionKey);
    } catch {
      return '';
    }
  }
  if (credential.secret_name) return input.getSecret(credential.secret_name) || '';
  return '';
}

export async function getHubFiscalDocument({
  baseUrl,
  hubDocumentId,
  token,
  fetcher = fetch,
}: GetHubFiscalDocumentInput): Promise<{ status: number; data: unknown }> {
  const normalizedBaseUrl = baseUrl.trim().replace(/\/$/, '');
  if (!token) return { status: 424, data: { error: {
    code: 'HUB_CREDENTIAL_UNAVAILABLE', message: 'Credencial indisponível para o emitente e ambiente do documento.',
  } } };
  if (!normalizedBaseUrl) {
    return {
      status: 503,
      data: { error: { code: 'HUB_BASE_URL_MISSING', message: 'HUB_FISCAL_BASE_URL não configurado' } },
    };
  }

  const url = new URL(`${normalizedBaseUrl}/hub_documents_get`);
  url.searchParams.set('id', hubDocumentId);

  try {
    const response = await fetcher(url, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
        'X-HubFiscal-Api-Version': HUB_API_VERSION,
      },
    });
    const text = await response.text();
    let data: unknown;
    try {
      data = text ? JSON.parse(text) : {};
    } catch {
      data = { parse_error: true };
    }
    return { status: response.status, data };
  } catch (error) {
    const message = (error as Error).message || 'Hub Fiscal indisponível';
    return {
      status: /rate limit|429/i.test(message) ? 429 : 503,
      data: { error: { message } },
    };
  }
}

export function classifyFiscalProviderStatus(rawStatus: string): FiscalPollOutcome {
  const status = rawStatus.toLowerCase();
  if (['authorized', 'autorizado', 'concluido', 'concluído', 'issued', 'emitida'].includes(status)) return 'issued';
  if (['rejected', 'rejeitado', 'rejeitada', 'denied', 'denegado', 'denegada'].includes(status)) return 'rejected';
  if (['cancelled', 'canceled', 'cancelado', 'cancelada'].includes(status)) return 'cancelled';
  return null;
}

export function safeProviderSnapshot(httpStatus: number, payload: unknown): JsonRecord {
  const envelope = asRecord(payload);
  const document = asRecord(envelope.document);
  const rawResponse = asRecord(document.raw_response_json);
  const rawError = asRecord(rawResponse.error);
  const error = asRecord(envelope.error);

  return {
    checked_at: new Date().toISOString(),
    http_status: httpStatus,
    provider_status: safeText(document.status ?? document.plugnotasStatus, 80),
    provider_code: safeText(document.cStat ?? error.code, 80),
    message: safeText(rawError.message ?? rawResponse.message ?? document.message ?? error.message),
  };
}

export function shouldDeadLetter(
  document: PollableFiscalDocument,
  hasProviderReference: boolean,
  now = Date.now(),
): boolean {
  const createdAt = Date.parse(document.created_at);
  const ageExceeded = Number.isFinite(createdAt) && now - createdAt >= MAX_POLL_AGE_MS;
  const attempts = (document.status_check_attempts ?? 0) + 1;
  const attemptLimit = hasProviderReference ? MAX_POLL_ATTEMPTS : MAX_MISSING_PROVIDER_ATTEMPTS;

  return ageExceeded || attempts >= attemptLimit;
}

export async function terminalizeFiscalPoll(
  admin: FiscalPollRpcClient,
  input: TerminalizeFiscalPollInput,
): Promise<void> {
  const { error } = await admin.rpc('terminalize_fiscal_poll_v1', {
    p_tenant_id: input.tenantId,
    p_document_kind: input.documentKind,
    p_document_id: input.documentId,
    p_document_number: input.documentNumber,
    p_reason_code: input.reasonCode,
    p_attempt_count: input.attemptCount,
    p_first_seen_at: input.firstSeenAt,
    p_context: input.context,
  });
  if (error) throw new Error('fiscal_dead_letter_terminalization_failed');
}

// enc:v1 remains compatible with existing records. Do not rotate the shared
// project key to repair one emitter: other integrations depend on that key.
function hexToBytes(hex: string) {
  const bytes = new Uint8Array(hex.length / 2);
  for (let i = 0; i < bytes.length; i++) bytes[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return bytes;
}
function bytesToHex(bytes: Uint8Array): string {
  return Array.from(bytes, value => value.toString(16).padStart(2, '0')).join('');
}
async function importLegacyKey(keyHex: string, usage: KeyUsage): Promise<CryptoKey> {
  if (!keyHex) throw new Error('Fiscal encryption key is missing');
  // Preserve the exact v1 derivation for historical credentials.
  return crypto.subtle.importKey('raw', hexToBytes(keyHex.padEnd(64, '0').slice(0, 64)), { name: 'AES-GCM' }, false, [usage]);
}
export async function decryptFiscalCredential(encrypted: string, keyHex: string): Promise<string> {
  const match = /^enc:v1:([a-fA-F0-9]{24}):((?:[a-fA-F0-9]{2}){17,})$/.exec(encrypted);
  if (!match) throw new Error('Invalid fiscal credential envelope');
  const key = await importLegacyKey(keyHex, 'decrypt');
  const plaintext = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: hexToBytes(match[1]) }, key, hexToBytes(match[2]));
  const token = new TextDecoder('utf-8', { fatal: true }).decode(plaintext);
  if (!token.trim()) throw new Error('Empty fiscal credential');
  return token;
}
export async function encryptFiscalCredential(token: string, keyHex: string): Promise<string> {
  if (!token.trim()) throw new Error('Empty fiscal credential');
  const key = await importLegacyKey(keyHex, 'encrypt');
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ciphertext = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, new TextEncoder().encode(token));
  const envelope = 'enc:v1:' + bytesToHex(iv) + ':' + bytesToHex(new Uint8Array(ciphertext));
  // Use the exact reader used by both emission and polling before saving.
  if (await decryptFiscalCredential(envelope, keyHex) !== token) throw new Error('Fiscal credential verification failed');
  return envelope;
}

export const HUB_ENVIRONMENTS = ['sandbox', 'homologation', 'production'] as const;
export type HubEnvironment = typeof HUB_ENVIRONMENTS[number];
export const HUB_DOCUMENT_SCOPES = ['all', 'nfse', 'cte', 'nfe', 'nfce', 'mdfe', 'nfcom'] as const;
export type HubDocumentScope = typeof HUB_DOCUMENT_SCOPES[number];

export class FiscalCredentialError extends Error {
  constructor(public readonly code: string, message: string) {
    super(message);
    this.name = 'FiscalCredentialError';
  }
}

export function requireHubEnvironment(...candidates: unknown[]): HubEnvironment {
  const supplied = candidates.filter(value => value !== undefined && value !== null);
  if (!supplied.length) throw new FiscalCredentialError('HUB_CREDENTIAL_ENVIRONMENT_REQUIRED', 'Informe explicitamente o ambiente fiscal.');
  if (supplied.some(value => !HUB_ENVIRONMENTS.includes(value as HubEnvironment))) {
    throw new FiscalCredentialError('HUB_CREDENTIAL_ENVIRONMENT_INVALID', 'Ambiente fiscal inválido.');
  }
  if (new Set(supplied).size !== 1) {
    throw new FiscalCredentialError('HUB_CREDENTIAL_ENVIRONMENT_MISMATCH', 'O ambiente solicitado difere do documento ou da configuração informada.');
  }
  return supplied[0] as HubEnvironment;
}

export function requireHubDocumentScope(value: unknown): HubDocumentScope {
  if (!HUB_DOCUMENT_SCOPES.includes(value as HubDocumentScope)) {
    throw new FiscalCredentialError('HUB_CREDENTIAL_SCOPE_INVALID', 'Escopo fiscal inválido.');
  }
  return value as HubDocumentScope;
}

type ScopedCredential = { doc_scope: string; environment: string | null; enabled?: boolean };

export function selectScopedHubCredential<T extends ScopedCredential>(
  credentials: readonly T[], scope: string, environment: HubEnvironment,
): T | null {
  requireHubDocumentScope(scope);
  requireHubEnvironment(environment);
  const eligible = credentials.filter(item => item.enabled !== false && item.environment === environment);
  for (const candidateScope of scope === 'all' ? ['all'] : [scope, 'all']) {
    const matches = eligible.filter(item => item.doc_scope === candidateScope);
    if (matches.length > 1) throw new FiscalCredentialError('HUB_CREDENTIAL_AMBIGUOUS', 'Mais de uma credencial habilitada para o mesmo escopo e ambiente.');
    if (matches.length === 1) return matches[0];
  }
  return null;
}

// Public API endpoint supplied by the operator; secrets remain server-side.
const DEFAULT_HUB_BASE_URL = 'https://rvgcsmuyvesusbxsqevr.supabase.co/functions/v1';
export function fiscalHubBaseUrl(configured: string | undefined): string {
  return (configured?.trim() || DEFAULT_HUB_BASE_URL).replace(/\/$/, '');
}
export class FiscalTransportConfigurationError extends Error {
  constructor(public readonly code: string, message: string) { super(message); this.name = 'FiscalTransportConfigurationError'; }
}
export function inspectFiscalTransport(baseUrl: string, token: string) {
  let normalizedBase: string | null = null;
  try {
    const url = new URL(baseUrl.trim());
    if (url.protocol === 'https:' && !url.username && !url.password && !url.search && !url.hash) normalizedBase = url.toString().replace(/\/$/, '');
  } catch { /* Return only configuration status, never an invalid raw value. */ }
  let credentialHeaderValid = false;
  if (token) {
    try { new Headers({ Authorization: 'Bearer ' + token }); credentialHeaderValid = true; } catch { /* Do not return the token or native error. */ }
  }
  return { baseConfigured: !!baseUrl.trim(), baseValid: normalizedBase !== null, baseUrl: normalizedBase, credentialReadable: !!token, credentialHeaderValid };
}
export function requireFiscalTransport(baseUrl: string, token: string): string {
  const state = inspectFiscalTransport(baseUrl, token);
  if (!state.baseConfigured) throw new FiscalTransportConfigurationError('HUB_BASE_URL_MISSING', 'O endereço da API do Hub Fiscal não está configurado no AGV Log (HUB_FISCAL_BASE_URL).');
  if (!state.baseValid) throw new FiscalTransportConfigurationError('HUB_BASE_URL_INVALID', 'O endereço da API do Hub Fiscal deve ser HTTPS, sem credenciais, parâmetros ou fragmento.');
  if (!state.credentialReadable) throw new FiscalTransportConfigurationError('HUB_CREDENTIAL_UNAVAILABLE', 'Credencial do emitente indisponível.');
  if (!state.credentialHeaderValid) throw new FiscalTransportConfigurationError('HUB_CREDENTIAL_HEADER_INVALID', 'O token contém caracteres inválidos para autenticação HTTP. Recadastre o token sem quebras de linha.');
  return state.baseUrl!;
}

/** Read-only lookup of one persisted integration reference. Never issues documents. */
export async function lookupFiscalOperation(baseUrl: string, token: string, reference: string, environment: string) {
  const base = requireFiscalTransport(baseUrl, token);
  const url = new URL(base + '/hub_documents_query');
  url.searchParams.set('idIntegracao', reference);
  url.searchParams.set('environment', environment);
  url.searchParams.set('type', 'cte');
  const response = await fetch(url, { method: 'GET', headers: { Authorization: 'Bearer ' + token, 'X-HubFiscal-Api-Version': '2026-08-27' } });
  const data = await response.json().catch(() => null);
  const obj = data && typeof data === 'object' && !Array.isArray(data) ? data as Record<string, unknown> : {};
  const nested = obj.data && typeof obj.data === 'object' && !Array.isArray(obj.data) ? obj.data as Record<string, unknown> : {};
  const candidate = [data, obj.documents, obj.items, obj.data, nested.documents, nested.items].find(Array.isArray);
  const rows = (candidate || (obj.document ? [obj.document] : [])) as unknown[];
  const error = obj.error && typeof obj.error === 'object' ? obj.error as Record<string, unknown> : {};
  const errorCode = typeof error.code === 'string' && /^[A-Z0-9_.-]{1,80}$/.test(error.code) ? error.code : null;
  const matches = rows.filter((row): row is Record<string, unknown> => !!row && typeof row === 'object' &&
    [(row as Record<string, unknown>).idIntegracao, (row as Record<string, unknown>).externalId].includes(reference));
  const safeText = (value: unknown) => typeof value === 'string' ? value.slice(0, 160) : null;
  return { httpStatus: response.status, providerSuccess: obj.success === true, errorCode,
    responseKeys: Object.keys(obj).slice(0, 20), dataKeys: Object.keys(nested).slice(0, 20), recordsReturned: rows.length,
    // Only exact-reference matches are returned. No fiscal payload, customer or token.
    matches: matches.map(row => ({ id: safeText(row.id), status: safeText(row.status), environment: safeText(row.environment), idIntegracao: safeText(row.idIntegracao), externalId: safeText(row.externalId) })) };
}

export const MAX_XML_BYTES=2_000_000;
export type EmissionIdentity={id:string;tenant_id:string;doc_type:'cte'|'nfse';environment:string;status:string;dispatch_state:string;hub_document_id:string;access_key:string|null;emitter_cnpj:string;number:string|null;series:string|null;authorization_protocol:string|null};
